// Entrypoint for news-image-20261119.
// The finished PNG is embedded as a single-line base64 payload below
// (injected by pack.mjs from entry.png, which draw.py renders).
// Running this file decodes the payload and writes /output/entry.png,
// or $MAKEFUN_OUTPUT_DIR/entry.png when that env var is set.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PAYLOAD = "";

function main(): void {
  const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
  const bytes = Buffer.from(PAYLOAD, "base64");
  // Sanity check: a real PNG is never tiny, and its decoded size must
  // match what the base64 length predicts (4 chars -> 3 bytes, minus padding).
  const padding = PAYLOAD.endsWith("==") ? 2 : PAYLOAD.endsWith("=") ? 1 : 0;
  const expected = Math.floor(PAYLOAD.length / 4) * 3 - padding;
  if (bytes.length !== expected || bytes.length < 1024) {
    throw new Error(`payload size mismatch: decoded ${bytes.length}, expected ${expected}`);
  }
  mkdirSync(outDir, { recursive: true });
  const target = join(outDir, "entry.png");
  writeFileSync(target, bytes);
  console.log(`wrote ${target} (${bytes.length} bytes)`);
}

main();
